def review_answer(state):
    citations_ok = all(claim in state["evidence"] for claim in state["claims"])
    return {**state, "review_status": "pass" if citations_ok else "needs_revision"}

def route(state):
    if state["review_status"] == "pass":
        return "final"
    return "revise"

state = {"claims": ["LangGraph uses nodes"], "evidence": ["LangGraph uses nodes"], "review_status": None}
reviewed = review_answer(state)
print(route(reviewed))
